public class ControlFlow {
    public static void main(String[] args) {
        for (int i = 1; i <= 5; i++) {
            if (i == 4) continue;
            String kind = switch (i % 3) {
                case 0 -> "fizz";
                default -> "num";
            };
            System.out.println(i + " " + kind);
        }
    }
}
